function cheatSheet(opts){
  opts=opts||{};
  var topic=(opts.topic||'主题').trim()||'主题';
  var items=String(opts.items||'').split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  var L=[];
  L.push('# '+topic+' 速查表');
  L.push('');
  L.push('| 语法/概念 | 说明 |');
  L.push('| --- | --- |');
  if(items.length){
    for(var i=0;i<items.length;i++){
      var p=items[i].split(/\s*[:：|]\s*/);
      var k=(p[0]||'').trim();
      var v=p.slice(1).join(' ').trim();
      L.push('| `'+(k||'____')+'` | '+(v||'（待补充）')+' |');
    }
  } else {
    L.push('| `____` | （待补充） |');
  }
  return L.join('\n');
}

var EXPORTS={cheatSheet:cheatSheet};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CheatSheetForgePure = EXPORTS; }
